def main():
    base=['gcloud','--project',os.environ['GCP_PROJECT_ID'],'--quiet']
    def gc(args):
        p=subprocess.run(base+args,text=True,capture_output=True,timeout=1100)
        if p.returncode:
            print('BATCH_OPERATOR_ERROR='+json.dumps({'command':args[:3],'classes':sorted(set(re.findall(r'\\b(?:PERMISSION_DENIED|INVALID_ARGUMENT|NOT_FOUND|UNAUTHENTICATED|DEADLINE_EXCEEDED)\\b',p.stderr)))}),flush=True)
